  'The Coach isn’t set up on this phone.': 'Le coach n’est pas configuré sur ce téléphone.',
  'The Coach needs your go-ahead first.': 'Le coach a d’abord besoin de ton accord.',
  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': 'La clé est conservée dans le stockage sécurisé de ce téléphone et n’en sort que pour appeler le fournisseur.',
  'This phone calls the provider directly with your key. Every request is charged to your account.': 'Ce téléphone appelle directement le fournisseur avec ta clé. Chaque requête est facturée sur ton compte.',
  'Turn the Coach off on this phone': 'Désactiver le coach sur ce téléphone',
  'Use my self-hosted Gains': 'Utiliser mon Gains auto-hébergé',
  'What leaves this phone': 'Ce qui quitte ce téléphone',
  'When you ask for a plan or a review, this phone sends the following straight to {0}, using your own API key. You pay for every request.': 'Quand tu demandes un plan ou une révision, ce téléphone envoie ce qui suit directement à {0}, avec ta propre clé API. Chaque requête est à ta charge.',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'Aucun coach n’est activé sur ton serveur. Demande à son admin, ou utilise ta propre clé ci-dessous.',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'Ton serveur fait tourner le coach avec le fournisseur choisi par son admin. Rien de nouveau ne quitte ce téléphone au-delà de ce qui se synchronise déjà.',
