  'A local model can take longer.': 'Un modèle local peut prendre plus de temps.',
  'All optional. The more the Coach knows, the less it guesses.': 'Tout est facultatif. Plus le coach en sait, moins il devine.',
  'Almost there': 'Presque fini',
