  'Before we start': 'Avant de commencer',
  'Building your plan…': 'Création de ton plan…',
  'Discarded. Tell me what was off and I will build a different one.': 'Abandonné. Dis-moi ce qui n’allait pas et j’en construis un autre.',
  'Done! Your plan is back to how it was before my last changes.': 'C’est fait ! Ton plan est revenu à l’état d’avant mes dernières modifications.',
  'Edit my answers': 'Modifier mes réponses',
