  'Experience': 'Expérience',
  'Goal, days, equipment, limits': 'Objectif, jours, matériel, limites',
  'Have a look at my training and tell me what you would change.': 'Regarde mon entraînement et dis-moi ce que tu changerais.',
  'Here is what I am working with:': 'Voici ce dont je dispose :',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'Salut, je suis ton coach. Je construis ton plan à partir de tes réponses et je l’ajuste d’après ce que tu enregistres vraiment. Rien ne change sans ton accord.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'J’ai tout passé en revue et je ne changerais rien pour l’instant. Continue comme ça, et redemande-moi après quelques séances.',
  'I understand, let’s go': 'Compris, c’est parti',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'Importé ! {0} routines sont dans ton plan et ta semaine est réglée. À la prochaine séance.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'Importé ! {0} routines sont dans ton plan. Ta semaine ne change pas ; planifie-les quand tu veux.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'Il conçoit ton plan à partir de quelques réponses et l’ajuste d’après ce que tu enregistres vraiment. Il ne change jamais rien sans ton accord, et chaque modification peut être annulée.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'Routines, exercices, séries et répétitions, ton planning hebdomadaire et tes réglages de progression.',
  'Your logged training': 'Ton entraînement enregistré',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes. Also your weekly check-in: how training felt, how you slept, and your note.': 'Les séries que tu as enregistrées sur la période du bilan : poids, répétitions, temps, notes d’effort, durée des séances et tes notes de séance. Et ton point hebdomadaire : ton ressenti de l’entraînement, ton sommeil et ta note.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'Les pesées de la même période, et ton poids cible si tu en as défini un.',
