  // --- triple progression (issue #179) ---
  'Triple progression': 'Triple progression',
  'Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.': 'Les reps montent jusqu’au haut de la fourchette, puis une série s’ajoute, jusqu’à ton maximum de séries. Toutes en haut et la charge monte, retour à tes premières séries et reps.',
